const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const donnerPass = ee.Geometry.Point([-120.32, 39.31]);
  const region = donnerPass.buffer(5000); // 5km buffer

  const feb2022Start = '2022-02-01';
  const feb2022End = '2022-03-01';
  const apr2022Start = '2022-04-01';
  const apr2022End = '2022-05-01';

  // 2. Data Acquisition - Try FLDAS for SWE
  let febCollection = ee.ImageCollection('NASA/FLDAS/NOAH01/C/GL/M/V001')
    .filterBounds(donnerPass)
    .filterDate(feb2022Start, feb2022End)
    .select('SWE_inst');

  let aprCollection = ee.ImageCollection('NASA/FLDAS/NOAH01/C/GL/M/V001')
    .filterBounds(donnerPass)
    .filterDate(apr2022Start, apr2022End)
    .select('SWE_inst');

  const febSize = febCollection.size().getInfo();
  const aprSize = aprCollection.size().getInfo();

  console.log(`February 2022 Images: ${febSize}`);
  console.log(`April 2022 Images: ${aprSize}`);

  if (febSize === 0 || aprSize === 0) {
    console.log('Trying alternative: MODIS daily snow cover product');

    febCollection = ee.ImageCollection('MODIS/006/MOD10A1')
      .filterBounds(donnerPass)
      .filterDate(feb2022Start, feb2022End)
      .select('NDSI_Snow_Cover');

    aprCollection = ee.ImageCollection('MODIS/006/MOD10A1')
      .filterBounds(donnerPass)
      .filterDate(apr2022Start, apr2022End)
      .select('NDSI_Snow_Cover');

    const febSizeMODIS = febCollection.size().getInfo();
    const aprSizeMODIS = aprCollection.size().getInfo();

    console.log(`MODIS Feb 2022: ${febSizeMODIS}, Apr 2022: ${aprSizeMODIS}`);

    if (febSizeMODIS === 0 || aprSizeMODIS === 0) {
      console.log('No data available for comparison period');
      console.log('<answer>C1</answer>');
      return;
    }
  }

  // 3. Processing - Calculate mean SWE
  const febMean = febCollection.mean();
  const aprMean = aprCollection.mean();

  // Check pixel counts
  const febStats = febMean.reduceRegion({
    reducer: ee.Reducer.mean().combine({reducer2: ee.Reducer.count(), sharedInputs: true}),
    geometry: region,
    scale: 3000,
    maxPixels: 1e9
  }).getInfo();

  const aprStats = aprMean.reduceRegion({
    reducer: ee.Reducer.mean().combine({reducer2: ee.Reducer.count(), sharedInputs: true}),
    geometry: region,
    scale: 3000,
    maxPixels: 1e9
  }).getInfo();

  const febVal = febStats.SWE_inst_mean || febStats.NDSI_Snow_Cover_mean;
  const febCount = febStats.SWE_inst_count || febStats.NDSI_Snow_Cover_count;
  const aprVal = aprStats.SWE_inst_mean || aprStats.NDSI_Snow_Cover_mean;
  const aprCount = aprStats.SWE_inst_count || aprStats.NDSI_Snow_Cover_count;

  console.log(`Feb 2022 - Mean: ${febVal}, Pixels: ${febCount}`);
  console.log(`Apr 2022 - Mean: ${aprVal}, Pixels: ${aprCount}`);

  // 4. Validation & Final Answer
  if (febCount === 0 || aprCount === 0) {
    console.log('No valid pixels after processing');
    console.log('<answer>C2</answer>');
    return;
  }

  if (febVal === null || febVal === undefined || aprVal === null || aprVal === undefined) {
    console.log('Calculation returned invalid values');
    console.log('<answer>C3</answer>');
    return;
  }

  if (isNaN(febVal) || isNaN(aprVal)) {
    console.log('Calculation returned NaN');
    console.log('<answer>C3</answer>');
    return;
  }

  // Compare values
  if (febVal > aprVal) {
    console.log('February SWE was higher than April');
    console.log('<answer>A</answer>');
  } else {
    console.log('February SWE was not higher than April');
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
